from pathlib import Path
p=Path('monarch-benchmark/workflowbench/wb_studio/analysis.py');s=p.read_text(encoding='utf8')
s=s.replace("        claim.write_text(hashlib.sha256(content.encode()).hexdigest(),encoding='utf-8')", "        analysis_scope = identity + '-analysis-v1'\n        remaining = Decimal(job['settings']['maximum_usd']) - studio.ledger.scope_committed(identity)\n        if remaining <= 0:\n            raise ValueError('This run has no remaining analysis budget. Unknown charges remain held.')\n        studio.ledger.reserve_run(analysis_scope, remaining, metadata={'parent_run': identity, 'purpose': 'post-run-analysis'})\n        claim.write_text(hashlib.sha256(content.encode()).hexdigest(),encoding='utf-8')")
s=s.replace("        response = gateway.request([{'role':'user','parts':[{'text':content}]}],RUBRIC,[],scope_id=identity,\n                     scope_limit_usd=Decimal(job['settings']['maximum_usd']),request_id=identity+'-analysis-v1')", "        with studio.runtime.provider('gemini', timeout=180):\n            response = gateway.request([{'role':'user','parts':[{'text':content}]}],RUBRIC,[],scope_id=analysis_scope,\n                         scope_limit_usd=remaining,request_id=identity+'-analysis-v1')")
s=s.replace("    write_json(folder / 'analysis.json',data)", "    studio.ledger.finish_run(analysis_scope)\n    write_json(folder / 'analysis.json',data)")
p.write_text(s,encoding='utf8')
